+use crate::api::client::ApiClient;
+use crate::models::{ResultWithDefaultError, TimeEntry};
+use crate::utilities;
+use std::collections::HashMap;
+
+const BILLING_INCREMENT_SECONDS: i64 = 15 * 60;
+const MINIMUM_ENTRY_SECONDS: i64 = 30 * 60;
+
+pub struct InvoiceCommand;
+
+fn billable_seconds(entry: &TimeEntry) -> Option<i64> {
+    if !entry.billable || entry.is_running() {
+        return None;
+    }
+
+    let rounded = ((entry.duration + BILLING_INCREMENT_SECONDS - 1)
+        / BILLING_INCREMENT_SECONDS)
+        * BILLING_INCREMENT_SECONDS;
+    Some(rounded.max(MINIMUM_ENTRY_SECONDS))
+}
+
+fn invoice_totals(entries: &[TimeEntry]) -> Vec<(String, i64)> {
+    let mut totals = HashMap::<String, i64>::new();
+    for entry in entries {
+        if let Some(seconds) = billable_seconds(entry) {
+            let project = entry
+                .project
+                .as_ref()
+                .map(|project| project.name.clone())
+                .unwrap_or_else(|| "No Project".to_string());
+            *totals.entry(project).or_default() += seconds;
+        }
+    }
+
+    let mut totals: Vec<_> = totals.into_iter().collect();
+    totals.sort_by(|(name_a, seconds_a), (name_b, seconds_b)| {
+        seconds_b.cmp(seconds_a).then_with(|| name_a.cmp(name_b))
+    });
+    totals
+}
+
+impl InvoiceCommand {
+    pub async fn execute(
+        api_client: impl ApiClient,
+        since: Option<String>,
+        until: Option<String>,
+    ) -> ResultWithDefaultError<()> {
+        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
+        let entries = api_client.get_time_entries_filtered(since, until).await?;
+        let totals = invoice_totals(&entries);
+
+        if totals.is_empty() {
+            println!("(no data)");
+            return Ok(());
+        }
+
+        let grand_total: i64 = totals.iter().map(|(_, seconds)| seconds).sum();
+        for (project, seconds) in totals {
+            println!("{seconds}s  {project}");
+        }
+        println!("{grand_total}s  Total");
+        Ok(())
+    }
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+    use chrono::Utc;
+
+    fn entry(duration: i64, billable: bool, project: Option<&str>, running: bool) -> TimeEntry {
+        TimeEntry {
+            id: 1,
+            description: String::new(),
+            start: Utc::now(),
+            stop: if running { None } else { Some(Utc::now()) },
+            duration: if running { -Utc::now().timestamp() } else { duration },
+            billable,
+            workspace_id: 1,
+            tags: vec![],
+            project: project.map(|name| crate::models::Project {
+                id: 1,
+                name: name.to_string(),
+                workspace_id: 1,
+                client: None,
+                is_private: false,
+                active: true,
+                at: Utc::now(),
+                created_at: Utc::now(),
+                color: String::new(),
+                billable: None,
+            }),
+            task: None,
+            created_with: None,
+        }
+    }
+
+    #[test]
+    fn rounds_then_applies_thirty_minute_floor() {
+        assert_eq!(billable_seconds(&entry(1, true, None, false)), Some(1800));
+        assert_eq!(billable_seconds(&entry(1800, true, None, false)), Some(1800));
+        assert_eq!(billable_seconds(&entry(1801, true, None, false)), Some(2700));
+    }
+
+    #[test]
+    fn excludes_non_billable_and_running_entries() {
+        assert_eq!(billable_seconds(&entry(3600, false, None, false)), None);
+        assert_eq!(billable_seconds(&entry(3600, true, None, true)), None);
+    }
+
+    #[test]
+    fn groups_and_sorts_totals() {
+        let entries = vec![
+            entry(1800, true, Some("Beta"), false),
+            entry(1800, true, Some("Alpha"), false),
+            entry(3600, true, Some("Beta"), false),
+            entry(1800, true, None, false),
+        ];
+        assert_eq!(
+            invoice_totals(&entries),
+            vec![("Beta".to_string(), 5400), ("Alpha".to_string(), 1800), ("No Project".to_string(), 1800)]
+        );
+    }
+}
